// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 value, address target, bytes memory data) public {
        vm.assume(target != address(c));
        vm.assume(target != address(0));
        vm.assume(value <= address(this).balance);
        address nonOwner = address(0x1234);
        vm.prank(nonOwner);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("withdraw(uint256)", 0));
        assertTrue(!success);
    }
}
